import React, { useState } from 'react';

const FeedbackSection = ({ masters, services }) => {
    const [masterName, setMasterName] = useState('');
    const [serviceName, setServiceName] = useState('');
    const [userName, setUserName] = useState('');
    const [feedbackText, setFeedbackText] = useState('');
    const [submitted, setSubmitted] = useState(false);

    const handleSubmit = async () => {
        const feedback = {
            masterName,
            serviceName,
            userName,
            feedbackText
        };

        try {
            const response = await fetch("http://localhost:8080/api/feedback", {
                method: "POST",
                headers: { "Content-Type": "application/json" },
                body: JSON.stringify(feedback)
            });

            if (response.ok) {
                setSubmitted(true);
                // Reset form
                setMasterName('');
                setServiceName('');
                setUserName('');
                setFeedbackText('');
            }
        } catch (err) {
            console.error("Failed to submit feedback", err);
        }
    };

    return (
        <section id="feedback" className="feedback-section">
            <h2>Feedback</h2>
            <div className="feedback-container">
                <div className="feedback-image">
                    <img src="/poster1.jpg" alt="Salon" />
                </div>
                <div className="feedback-form">
                    <label>Choose Master:</label>
                    <select value={masterName} onChange={(e) => setMasterName(e.target.value)}>
                        <option value="">Select Master</option>
                        {masters.map(master => (
                            <option key={master.id} value={master.name}>{master.name}</option>
                        ))}
                    </select>

                    <label>Choose Service:</label>
                    <select value={serviceName} onChange={(e) => setServiceName(e.target.value)}>
                        <option value="">Select Service</option>
                        {services.map(service => (
                            <option key={service.id} value={service.name}>{service.name}</option>
                        ))}
                    </select>

                    <label>Your Name:</label>
                    <input
                        type="text"
                        placeholder="Your Name"
                        value={userName}
                        onChange={(e) => setUserName(e.target.value)}
                    />

                    <label>Your Feedback:</label>
                    <textarea
                        placeholder="Your Feedback"
                        value={feedbackText}
                        onChange={(e) => setFeedbackText(e.target.value)}
                    ></textarea>

                    <button className="submit-feedback" onClick={handleSubmit}>Submit Feedback</button>

                    {submitted && <p style={{ color: 'green' }}>Feedback submitted!</p>}
                </div>
            </div>
        </section>
    );
};

export default FeedbackSection;
